mkdir -p "$TMPDIR/bw-scripts" "$TMPDIR/bw-run" "$TMPDIR/bw-shots" && cat > "$TMPDIR/bw-scripts/probe.py" <<'EOF'
import sys, json
from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    for label, kwargs in [
        ("default-headless", dict(headless=True)),
        ("swiftshader", dict(headless=True, args=["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"])),
    ]:
        try:
            b = p.chromium.launch(**kwargs)
            pg = b.new_page()
            pg.set_content("<canvas id=c></canvas>")
            info = pg.evaluate("""() => {
              const c = document.getElementById('c');
              const gl2 = c.getContext('webgl2');
              const out = {webgl2: !!gl2};
              if (gl2) {
                const ext = gl2.getExtension('WEBGL_debug_renderer_info');
                out.renderer = ext ? gl2.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl2.getParameter(gl2.RENDERER);
                out.maxVtxTex = gl2.getParameter(gl2.MAX_VERTEX_TEXTURE_IMAGE_UNITS);
                out.maxAttribs = gl2.getParameter(gl2.MAX_VERTEX_ATTRIBS);
                out.pointSizeRange = Array.from(gl2.getParameter(gl2.ALIASED_POINT_SIZE_RANGE));
              }
              return out;
            }""")
            print(label, b.version, json.dumps(info))
            b.close()
        except Exception as e:
            print(label, "FAILED:", str(e)[:400])
EOF
cd "$TMPDIR/bw-run" && python3 "$TMPDIR/bw-scripts/probe.py" 2>&1 | head -30

