const GRAV = 0.60;          // display-time gravity (world units / s^2)

/* ---------------------------------------------------------------------
   2. Balloon geometry (teardrop with hydrostatic sag) and bullet kinematics
   --------------------------------------------------------------------- */
const PROF = { yBot: -1.42, yWid: -0.10, yNeck: 1.50, yTop: 1.94, rMax: 1.26, rNeck: 0.115 };
const WATER_SCALE = 0.985;
const Y_KEEP = 1.05;        // latex above this height survives as the knotted remnant on the tether
const ROWS = 150, COLS = 144;

/* Radius of the analytic bulb for yBot <= y <= yNeck */
function profileRadius(y) {
  const P = PROF;
  if (y <= P.yWid) {
    const e = (y - P.yWid) / (P.yWid - P.yBot);
    return P.rMax * Math.sqrt(Math.max(0, 1 - e * e));
  }
  const s = clamp((y - P.yWid) / (P.yNeck - P.yWid), 0, 1);
  return P.rNeck + (P.rMax - P.rNeck) * 0.5 * (1 + Math.cos(Math.PI * s));
}

function buildProfilePolyline() {
  const P = PROF, pts = [];
  const b = P.yWid - P.yBot;
  for (let i = 0; i <= 72; i++) {            // lower half ellipse, pole to equator
    const th = -Math.PI / 2 + (Math.PI / 2) * (i / 72);
    pts.push({ r: P.rMax * Math.cos(th), y: P.yWid + b * Math.sin(th) });
  }
  for (let i = 1; i <= 110; i++) {           // taper into the neck
    const s = i / 110;
    pts.push({ r: P.rNeck + (P.rMax - P.rNeck) * 0.5 * (1 + Math.cos(Math.PI * s)), y: P.yWid + s * (P.yNeck - P.yWid) });
  }
  const k = [[0.10, 0.112], [0.20, 0.104], [0.28, 0.100], [0.33, 0.118], [0.37, 0.150], [0.40, 0.158],
             [0.42, 0.146], [0.435, 0.105], [0.442, 0.050], [0.444, 0.0]];
  for (const q of k) pts.push({ r: q[1], y: P.yNeck + q[0] });
  pts[0].r = 0;
  return pts;
}

