  float ndv = clamp(dot(N, V), 0.0, 1.0);
  float Fr = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);
  vec3 refl = studio(reflect(-V, N), 0.03) * (Fr + 0.05);

  vec3 d1 = refract(-V, N, 1.0 / 1.33);
  vec3 ne = N + 2.0 * dot(-N, d1) * d1;
  vec3 d2 = refract(d1, -ne, 1.33);
  if (dot(d2, d2) < 0.5) d2 = reflect(d1, -ne);
  vec3 refr = studio(normalize(d2), 0.02);

  float since = t - tearTime(vRest, vS);
  vec3 tint = mix(vec3(1.0, 0.62, 0.64), vec3(0.86, 0.95, 1.0), smoothstep(0.0, 1.8, since));
  float edgeW = pow(1.0 - ndv, 2.0);
  vec3 C = refl + refr * (1.0 - Fr) * tint * (0.35 + 0.9 * edgeW);
  C += tint * vec3(0.012, 0.014, 0.02) * (1.0 - edgeW);
  C += vec3(0.8, 0.92, 1.0) * (lip * 0.9 + holeEdge * 0.6);

  float a = clamp(Fr + 0.05 + 0.34 * edgeW + 0.5 * lip + 0.4 * holeEdge, 0.0, 0.95);
  a *= expo * side;
  gl_FragColor = vec4(enc(filmic(C * side)) * a, a);
}
`;

input.new_string:
  float ndv = clamp(dot(N, V), 0.0, 1.0);
  float Fr = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);
  // glossy softbox highlights are far brighter than the 2% Fresnel base suggests, so they get a luminance boost
  vec3 refl = studio(reflect(-V, N), 0.025) * (Fr * 3.2 + 0.07);

  vec3 d1 = refract(-V, N, 1.0 / 1.33);
  vec3 ne = N + 2.0 * dot(-N, d1) * d1;
  vec3 d2 = refract(d1, -ne, 1.33);
  if (dot(d2, d2) < 0.5) d2 = reflect(d1, -ne);
  vec3 refr = studio(normalize(d2), 0.02);

  float since = t - tearTime(vRest, vS);
  vec3 tint = mix(vec3(1.0, 0.60, 0.62), vec3(0.84, 0.94, 1.0), smoothstep(0.0, 2.2, since));
  float edgeW = pow(1.0 - ndv, 2.0);
  float turb = smoothstep(3.4, 6.0, t);
  float foam = vnoise(vRest * 5.5 + vec3(0.0, t * 0.1, 0.0));
  vec3 C = refl + refr * (1.0 - Fr) * tint * (0.45 + 1.1 * edgeW);
  C += tint * vec3(0.030, 0.040, 0.060) * (0.35 + 0.65 * ndv) * (1.0 + 2.2 * turb * foam);     // water body glow, milky when aerated
  C += vec3(0.8, 0.92, 1.0) * (lip * 0.9 + holeEdge * 0.6);

  float a = clamp(Fr * 1.4 + 0.07 + 0.30 * edgeW + 0.12 * turb * foam + 0.5 * lip + 0.4 * holeEdge, 0.0, 0.95);
  a *= expo * side;
  gl_FragColor = vec4(enc(filmic(C * side)) * min(1.0, expo * 1.5), a);
}
`;

