import sys, base64
from playwright.sync_api import sync_playwright

# usage: edge.py rowStart rowEnd file1 file2 ...   -> rightmost strongly-red pixel per sampled row
def main():
    r0, r1 = int(sys.argv[1]), int(sys.argv[2])
    files = sys.argv[3:]
    with sync_playwright() as p:
        b = p.chromium.launch(headless=True)
        pg = b.new_page()
        pg.set_content("<canvas id=c></canvas>")
        for f in files:
            data = base64.b64encode(open(f, "rb").read()).decode()
            res = pg.evaluate("""async ([d, r0, r1]) => {
              const img = new Image(); img.src = 'data:image/png;base64,' + d; await img.decode();
              const c = document.getElementById('c'); c.width = img.width; c.height = img.height;
              const g = c.getContext('2d'); g.drawImage(img, 0, 0);
              const out = [];
              for (let y = r0; y <= r1; y += 10) {
                const row = g.getImageData(0, y, img.width, 1).data;
                let rx = -1;
                for (let x = img.width - 1; x >= 0; x--) {
                  const R = row[x*4], G = row[x*4+1], B = row[x*4+2];
                  if (R > 120 && G < 90 && B < 90) { rx = x; break; }
                }
                out.push([y, rx]);
              }
              return out;
            }""", [data, r0, r1])
            print(f.split("/")[-1], res)
        b.close()
main()

