import sys
from playwright.sync_api import sync_playwright

ROOT = "/private/tmp/pcd-sbx-claude-sonnet-5.5-y5gvfq3v"
HTML = "file://" + ROOT + "/work/index.html"
THREE = ROOT + "/tmp/bw-three/three.r128.min.js"

JS = """() => {
  const gl = renderer.getContext();
  const out = {};
  for (const t of [0, 1.3, 3.2, 4.2, 6.0, 8.0]) {
    renderAt(t); gl.finish();
    const t0 = performance.now();
    const N = 6;
    for (let i = 0; i < N; i++) { renderAt(t + i * 0.001); gl.finish(); }
    out[t] = +((performance.now() - t0) / N).toFixed(1);
  }
  return out;
}"""

with sync_playwright() as p:
    for label, args, vp in [("metal 1920x1080", ["--use-gl=angle", "--use-angle=metal"], (1920, 1080)),
                            ("swiftshader 1280x720", ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"], (1280, 720)),
                            ("swiftshader 1920x1080", ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"], (1920, 1080))]:
        b = p.chromium.launch(headless=True, args=["--ignore-gpu-blocklist"] + args)
        ctx = b.new_context(viewport={"width": vp[0], "height": vp[1]}, device_scale_factor=1)
        page = ctx.new_page()
        page.route("**/three.min.js", lambda route: route.fulfill(path=THREE, content_type="application/javascript"))
        page.goto(HTML)
        page.wait_for_function("typeof renderAt === 'function'", timeout=30000)
        page.wait_for_timeout(300)
        page.click("#btn-toggle")
        print(label, page.evaluate(JS))
        b.close()

