import sys
from playwright.sync_api import sync_playwright

ROOT = "/private/tmp/pcd-sbx-claude-sonnet-5.5-y5gvfq3v"
HTML = "file://" + ROOT + "/work/index.html"
THREE = ROOT + "/tmp/bw-three/three.r128.min.js"

JS = """() => {
  const gl = renderer.getContext();
  const buf = new Uint8Array(4);
  const meshes = scene.children.filter(o => o.isMesh);
  const names = meshes.map((m, i) => i + ':' + (m.material.type) + ':r' + m.renderOrder);
  const timeIt = (t) => {
    renderAt(t); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, buf);
    const t0 = performance.now(); const N = 5;
    for (let i = 0; i < N; i++) { renderAt(t + i * 0.001); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, buf); }
    return +((performance.now() - t0) / N).toFixed(1);
  };
  const out = { names };
  for (const t of [1.3, 4.2, 6.0]) {
    const row = { all: timeIt(t) };
    meshes.forEach((m, i) => {
      m.visible = false;
      row['-' + names[i]] = timeIt(t);
      m.visible = true;
    });
    out[t] = row;
  }
  return out;
}"""

with sync_playwright() as p:
