793:const FS_WATER = () => glslCommon() + glslFragCommon() + `
793: const FS_WATER = () => glslCommon() + glslFragCommon() + `
794: varying vec3 vRest;
795: varying vec3 vWPos;
796: varying vec3 vWNrm;
797: varying float vS;
798: void main() {
799:   float t = uTime;
800:   float rimU;
801:   float alive = latexAlive(vRest, vS, t, rimU);
802:   float expo = 1.0 - alive;
803:   if (expo < 0.01) discard;
804:   float rho = length(vRest.yz);
805:   float rHole = (vRest.x > 0.0) ? rEntryHole(t) : rExitHole(t);
806:   if (rho < rHole) discard;
807:   float holeEdge = exp(-(rho - rHole) * 18.0) * step(0.001, rHole);
808: 
809:   float Pd = clamp((t - T_DIS0) / (T_DIS1 - T_DIS0), 0.0, 1.0);
810:   float th = mix(LACE_LO, LACE_HI, Pd);
811:   float Lf = lace(vRest) + 0.07 * (vnoise(vRest * 12.0) - 0.5);
812:   float dd = Lf - th;
813:   if (dd < 0.0) discard;
814:   float lip = exp(-dd * 20.0) * smoothstep(0.0, 0.03, Pd);
815: 
816:   vec3 V = normalize(cameraPosition - vWPos);
817:   vec3 N = normalize(vWNrm);
818:   float side = 1.0;
819:   if (dot(N, V) < 0.0) { N = -N; side = 0.5; }      // far wall seen from inside: dimmer, winding independent
820: 
821:   float bumpAmp = 0.05 * smoothstep(1.2, 2.2, t) + 0.12 * smoothstep(3.5, 6.0, t);
822:   vec3 q = vRest * 8.0 + vec3(0.0, 0.0, t * 0.05);
823:   vec3 g = vec3(vnoise(q + vec3(0.37, 0.0, 0.0)) - vnoise(q - vec3(0.37, 0.0, 0.0)),
824:                 vnoise(q + vec3(0.0, 0.37, 0.0)) - vnoise(q - vec3(0.0, 0.37, 0.0)),
825:                 vnoise(q + vec3(0.0, 0.0, 0.37)) - vnoise(q - vec3(0.0, 0.0, 0.37)));
826:   N = normalize(N + bumpAmp * (g - dot(g, N) * N));
827: 
828:   float ndv = clamp(dot(N, V), 0.0, 1.0);
829:   float Fr = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);
830:   // glossy softbox highlights are far brighter than the 2% Fresnel base suggests, so they get a luminance boost
831:   vec3 refl = studio(reflect(-V, N), 0.03) * (Fr * 1.7 + 0.010);
832: 
833:   vec3 d1 = refract(-V, N, 1.0 / 1.33);
834:   vec3 ne = N + 2.0 * dot(-N, d1) * d1;
835:   vec3 d2 = refract(d1, -ne, 1.33);
836:   if (dot(d2, d2) < 0.5) d2 = reflect(d1, -ne);
837:   vec3 refr = studio(normalize(d2), 0.02);
838: 
839:   float since = t - tearTime(vRest, vS);
840:   vec3 tint = mix(vec3(1.0, 0.74, 0.76), vec3(0.88, 0.96, 1.0), smoothstep(0.0, 1.8, since));
841:   float edgeW = pow(1.0 - ndv, 2.0);
842:   float turb = smoothstep(3.4, 6.0, t);
843:   float foam = vnoise(vRest * 5.5 + vec3(0.0, t * 0.1, 0.0));
844:   vec3 C = refl + refr * (1.0 - Fr) * tint * (0.40 + 1.0 * edgeW);
845:   C += tint * vec3(0.010, 0.013, 0.019) * (0.35 + 0.65 * ndv) * (1.0 + 4.0 * turb * foam);     // water body glow, milky when aerated
846:   C += vec3(0.8, 0.92, 1.0) * (lip * 0.9 + holeEdge * 0.6);
847: 
848:   float a = clamp(Fr * 1.4 + 0.07 + 0.30 * edgeW + 0.12 * turb * foam + 0.5 * lip + 0.4 * holeEdge, 0.0, 0.95);
849:   a *= expo * side;
850:   gl_FragColor = vec4(enc(filmic(C * side)) * min(1.0, expo * 1.5), a);
851: }
852: `;

