import sys
from playwright.sync_api import sync_playwright

ROOT = "/private/tmp/pcd-sbx-claude-sonnet-5.5-y5gvfq3v"
HTML = "file://" + ROOT + "/work/index.html"
THREE = ROOT + "/tmp/bw-three/three.r128.min.js"

JS = """() => {
  const gl = renderer.getContext();
  const buf = new Uint8Array(4);
  const meshes = scene.children.filter(o => o.isMesh);
  const timeIt = (t) => {
    renderAt(t); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, buf);
    const t0 = performance.now(); const N = 5;
    for (let i = 0; i < N; i++) { renderAt(t + i * 0.001); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, buf); }
    return +((performance.now() - t0) / N).toFixed(1);
  };
  const out = {};
  const t = 1.3;
  meshes.forEach(m => m.material.visible = false);
  out.nothing = timeIt(t);
  const parts = meshes[6];
  parts.material.visible = true;
  const full = parts.geometry.instanceCount;
  for (const n of [0, 500, 2000, full]) { parts.geometry.instanceCount = n; out['parts n=' + n] = timeIt(t); }
  parts.geometry.instanceCount = full;
  parts.material.visible = false;
  meshes.forEach((m, i) => { m.material.visible = true; });
  parts.material.visible = false;
  out.noparts = timeIt(t);
  return out;
}"""

with sync_playwright() as p:
    b = p.chromium.launch(headless=True, args=["--ignore-gpu-blocklist", "--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"])
    ctx = b.new_context(viewport={"width": 1280, "height": 720}, device_scale_factor=1)
    page = ctx.new_page()
    page.route("**/three.min.js", lambda route: route.fulfill(path=THREE, content_type="application/javascript"))
    page.goto(HTML)
    page.wait_for_function("typeof renderAt === 'function'", timeout=30000)
    page.wait_for_timeout(300)
    page.click("#btn-toggle")
    print(page.evaluate(JS))
    b.close()

