214	</div>
215	
216	<script>
217	/* =====================================================================
218	   BALLISTICS: projectile through a suspended water balloon, 15,000 FPS look.
219	   Every visual is a pure function of simTime (renderAt). All randomness is
220	   drawn once, at start-up, from a Mulberry32 generator seeded with 42.
221	   ===================================================================== */
222	
223	/* ---------------------------------------------------------------------
224	   1. Timeline constants and deterministic PRNG
225	   --------------------------------------------------------------------- */
226	const DURATION = 8.000;
227	const SEED = 42;
228	
229	function mulberry32(seed) {
230	  let a = seed >>> 0;
231	  return function () {
232	    a = (a + 0x6D2B79F5) >>> 0;
233	    let t = a;
234	    t = Math.imul(t ^ (t >>> 15), t | 1);
235	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
236	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
237	  };
238	}
239	let rng = mulberry32(SEED);
240	function resetRNG() { rng = mulberry32(SEED); }
241	const rnd = () => rng();
242	const rrange = (a, b) => a + (b - a) * rng();
243	
244	const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
245	const smoothstep = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
246	
247	/* Phase boundaries in simTime seconds (spec section 2) */
248	const T_HIT = 1.000;        // bullet tip touches the latex
249	const T_PUNC = 1.170;       // latex punctured, tear starts
250	const T_TEAR_END = 1.600;   // membrane fully retracted
251	const T_STASIS_END = 2.400; // ghost-balloon water mass holds its shape until here
252	const T_EXIT = 3.800;       // bullet emerges from the left boundary
253	const T_CONE_END = 5.000;   // forward plume phase ends
254	const GRAV = 0.32;         // display-time gravity (world units / s^2)
255	
256	/* ---------------------------------------------------------------------
257	   2. Balloon geometry (pendant-drop teardrop with hydrostatic sag) and bullet kinematics
258	   --------------------------------------------------------------------- */
259	const PROF = { yBot: -1.40, yWid: -0.12, yNeck: 1.38, yTop: 1.80, rMax: 1.27, rNeck: 0.125 };
260	const WATER_SCALE = 0.985;
261	const Y_KEEP = 1.18;        // latex above this height survives as the knotted remnant on the tether
262	const ROWS = 104, COLS = 92;
263	const TAPER_POW = 1.28;     // fuller shoulders: the bulb narrows late, then flares into the neck
264	
265	function taperF(s) { return 0.5 * (1 + Math.cos(Math.PI * Math.pow(clamp(s, 0, 1), TAPER_POW))); }
266	
267	/* Radius of the analytic bulb for yBot <= y <= yNeck */
268	function profileRadius(y) {
269	  const P = PROF;
270	  if (y <= P.yWid) {
271	    const e = (y - P.yWid) / (P.yWid - P.yBot);
272	    return P.rMax * Math.sqrt(Math.max(0, 1 - e * e));
273	  }
274	  const s = clamp((y - P.yWid) / (P.yNeck - P.yWid), 0, 1);
275	  return P.rNeck + (P.rMax - P.rNeck) * taperF(s);
276	}
277	
278	function buildProfilePolyline() {
279	  const P = PROF, pts = [];
280	  const b = P.yWid - P.yBot;
281	  for (let i = 0; i <= 72; i++) {            // lower half ellipse, pole to equator
282	    const th = -Math.PI / 2 + (Math.PI / 2) * (i / 72);
283	    pts.push({ r: P.rMax * Math.cos(th), y: P.yWid + b * Math.sin(th) });
284	  }
285	  for (let i = 1; i <= 110; i++) {           // taper into the neck
286	    const s = i / 110;
287	    pts.push({ r: P.rNeck + (P.rMax - P.rNeck) * taperF(s), y: P.yWid + s * (P.yNeck - P.yWid) });
288	  }
289	  const k = [[0.08, 0.118], [0.16, 0.108], [0.22, 0.104], [0.27, 0.122], [0.31, 0.152], [0.34, 0.160],
290	             [0.365, 0.148], [0.385, 0.108], [0.397, 0.052], [0.402, 0.0]];
291	  for (const q of k) pts.push({ r: q[1], y: P.yNeck + q[0] });
292	  pts[0].r = 0;
293	  return pts;
294	}
295	
296	/* Resample the profile at uniform arc length and attach analytic normals. */
297	function buildRows() {
298	  const pts = buildProfilePolyline(), n = pts.length, cum = new Array(n).fill(0);
299	  for (let i = 1; i < n; i++) cum[i] = cum[i - 1] + Math.hypot(pts[i].r - pts[i - 1].r, pts[i].y - pts[i - 1].y);
300	  const total = cum[n - 1], rows = [];
301	  let seg = 0;
302	  for (let i = 0; i < ROWS; i++) {
303	    const s = total * i / (ROWS - 1);
304	    while (seg < n - 2 && cum[seg + 1] < s) seg++;
305	    const f = (s - cum[seg]) / Math.max(cum[seg + 1] - cum[seg], 1e-9);
306	    rows.push({ r: pts[seg].r + (pts[seg + 1].r - pts[seg].r) * f, y: pts[seg].y + (pts[seg + 1].y - pts[seg].y) * f, s });
307	  }
308	  for (let i = 0; i < ROWS; i++) {
309	    const a = rows[Math.max(i - 1, 0)], b = rows[Math.min(i + 1, ROWS - 1)];
310	    const dr = b.r - a.r, dy = b.y - a.y, l = Math.hypot(dr, dy) || 1;
311	    rows[i].nr = dy / l; rows[i].ny = -dr / l;
312	  }
313	  rows[0].r = 0; rows[0].nr = 0; rows[0].ny = -1;
314	  rows[ROWS - 1].r = 0; rows[ROWS - 1].nr = 0; rows[ROWS - 1].ny = 1;
315	  return rows;
316	}
317	const ROWS_DATA = buildRows();
318	
319	/* Arc-length coordinate of the impact point (y = 0 on the ascending side) */
320	function arcAtY(y) {
321	  for (let i = 1; i < ROWS; i++) {
322	    const a = ROWS_DATA[i - 1], b = ROWS_DATA[i];
323	    if (a.y <= y && b.y >= y && b.y > a.y) return a.s + (b.s - a.s) * (y - a.y) / (b.y - a.y);
324	  }
325	  return 0;
326	}
327	const R0 = profileRadius(0.0);                 // balloon radius on the bullet axis
328	const S_IMPACT = arcAtY(0.0);
329	const X_HIT = R0 + 0.014;                      // latex contact point
330	const X_EXIT = -R0 * WATER_SCALE;              // water surface the bullet leaves through
331	const S_EXIT = X_HIT - X_EXIT;
332	const BUL_SCALE = 1.1, BUL_LEN = 0.66;      // local bullet length; mesh is scaled by BUL_SCALE
333	const R_BUL = 0.082 * BUL_SCALE;
334	
335	/* Bullet speed profile (display units / s): fast approach, speed ramp into the
336	   slow-motion contact, decelerating run through the water, ramp-out after exit. */
337	const V_C = 12.5, V_I = 1.4, RAMP_A = 0.60;
338	const DT_W = T_EXIT - T_HIT;
339	const A_W = 2 * (V_I * DT_W - S_EXIT) / (DT_W * DT_W);
340	const V_E = V_I - A_W * DT_W;
341	const V_O = 8.0, RAMP_OUT = 0.7;
342	
343	function bulletTipX(t) {
344	  if (t <= T_HIT) {
345	    const RA = RAMP_A, RB = T_HIT;
346	    let integ;
347	    if (t <= RA) integ = (RA - t) + 0.5 * (RB - RA);
348	    else { const w = (t - RA) / (RB - RA); integ = (RB - RA) * ((1 - w) - 0.5 + (w * w * w - 0.5 * w * w * w * w)); }
349	    return X_HIT + V_I * (T_HIT - t) + (V_C - V_I) * integ;
350	  }
351	  if (t <= T_EXIT) { const tau = t - T_HIT; return X_HIT - (V_I * tau - 0.5 * A_W * tau * tau); }
352	  const tau = t - T_EXIT;
353	  let ramp;
354	  if (tau < RAMP_OUT) { const w = tau / RAMP_OUT; ramp = RAMP_OUT * (w * w * w - 0.5 * w * w * w * w); }
355	  else ramp = RAMP_OUT * 0.5 + (tau - RAMP_OUT);
356	  return X_EXIT - (V_E * tau + (V_O - V_E) * ramp);
357	}
358	function tPassDepthJS(s) {
359	  const disc = Math.max(V_I * V_I - 2 * A_W * s, 0);
360	  return T_HIT + (V_I - Math.sqrt(disc)) / A_W;
361	}
362	
363	/* Tear front distance metric, mirrored in GLSL */
364	let D_MAX = 1;
365	(function () {
366	  let m = 0;
367	  for (const r of ROWS_DATA) {
368	    if (r.y > Y_KEEP || r.y < PROF.yBot + 0.35) continue;
369	    m = Math.max(m, Math.hypot(r.s - S_IMPACT, r.r * Math.PI));
370	  }
371	  D_MAX = m;
372	})();
