from playwright.sync_api import sync_playwright

ROOT = "/private/tmp/pcd-sbx-claude-sonnet-5.5-y5gvfq3v"
HTML = "file://" + ROOT + "/work/index.html"
THREE = ROOT + "/tmp/bw-three/three.r128.min.js"

JS = """() => {
  const r = (el) => { const b = el.getBoundingClientRect(); return [Math.round(b.left * 100) / 100, Math.round(b.top * 100) / 100, Math.round(b.width * 100) / 100, Math.round(b.height * 100) / 100]; };
  const out = {};
  out.viewport = [innerWidth, innerHeight];
  out.dock = r(document.getElementById('dock'));
  out.refire = r(document.getElementById('btn-refire'));
  out.toggle = r(document.getElementById('btn-toggle'));
  out.pills = Array.from(document.querySelectorAll('.speed-pill')).map(r);
  out.seps = Array.from(document.querySelectorAll('.dock-sep')).map(r);
  out.scrubber = r(document.getElementById('scrubber'));
  out.countdown = r(document.getElementById('countdown'));
  out.bodyChildren = Array.from(document.body.children).map(e => e.tagName + (e.id ? '#' + e.id : ''));
  out.visibleText = document.body.innerText.replace(/\\s+/g, ' ').trim();
  out.canvasStyle = [getComputedStyle(document.getElementById('stage')).width, getComputedStyle(document.getElementById('stage')).height];
  out.dockStyle = (() => { const s = getComputedStyle(document.getElementById('dock')); return {bottom: s.bottom, width: s.width, height: s.height, radius: s.borderRadius, padding: s.padding, gap: s.gap}; })();
  return out;
}"""

with sync_playwright() as p:
    b = p.chromium.launch(headless=True, args=["--ignore-gpu-blocklist", "--use-gl=angle", "--use-angle=metal"])
    page = b.new_context(viewport={"width": 1920, "height": 1080}).new_page()
    page.route("**/three.min.js", lambda route: route.fulfill(path=THREE, content_type="application/javascript"))
    page.goto(HTML)
    page.wait_for_function("typeof renderAt === 'function'", timeout=30000)
    page.wait_for_timeout(300)
    res = page.evaluate(JS)
    for k, v in res.items():
        print(k, v)
    b.close()

