from playwright.sync_api import sync_playwright

ROOT = "/private/tmp/pcd-sbx-claude-sonnet-5.5-y5gvfq3v"
HTML = "file://" + ROOT + "/work/index.html"
THREE = ROOT + "/tmp/bw-three/three.r128.min.js"

JS = """async () => {
  const c = document.getElementById('stage');
  const hash = async (s) => { const b = new TextEncoder().encode(s); const d = await crypto.subtle.digest('SHA-256', b); return Array.from(new Uint8Array(d)).slice(0, 6).map(x => x.toString(16).padStart(2, '0')).join(''); };
  const grab = async (t) => { renderAt(t); const url = c.toDataURL('image/png'); return [url.length, await hash(url)]; };
  const out = {};
  out.a1 = await grab(3.0);
  out.b = await grab(6.5);
  out.a2 = await grab(3.0);
  out.zero1 = await grab(0);
  out.zero2 = await grab(0);
  // non-blank check: count non-transparent pixels in the read-back
  renderAt(3.0);
  const g = document.createElement('canvas'); g.width = c.width; g.height = c.height;
  const ctx = g.getContext('2d'); ctx.drawImage(c, 0, 0);
  const d = ctx.getImageData(0, 0, g.width, g.height).data;
  let nz = 0; for (let i = 3; i < d.length; i += 4) if (d[i] > 8) nz++;
  out.nonTransparentPixels = nz; out.totalPixels = d.length / 4;
  return out;
}"""

with sync_playwright() as p:
    for label, args in [("metal", ["--use-gl=angle", "--use-angle=metal"]), ("swiftshader", ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"])]:
        b = p.chromium.launch(headless=True, args=["--ignore-gpu-blocklist"] + args)
        page = b.new_context(viewport={"width": 960, "height": 540}).new_page()
        page.route("**/three.min.js", lambda route: route.fulfill(path=THREE, content_type="application/javascript"))
        page.goto(HTML)
        page.wait_for_function("typeof renderAt === 'function'", timeout=30000)
        page.click("#btn-toggle")
        r = page.evaluate(JS)
        print(label, r, "| deterministic:", r["a1"] == r["a2"] and r["zero1"] == r["zero2"] and r["a1"] != r["b"])
        b.close()

